import java.util.*;
import java.io.*;

public class Main {
    static Scanner scanner = new Scanner(System.in);
    static long[][][] memoization;
    static int MOD = 998244353;

    public static void main(String[] args) {
        int testCount = 1;
        while (testCount-- > 0) {
            String line = scanner.nextLine();
            char[] A = line.toCharArray();
            if (A.length == 1 && A[0] == '0') {
                System.out.println("1");
                return;
            }
            if (A[0] == '0') {
                System.out.println("0");
                return;
            }
            if (A.length == 1 && (A[0] == 'X' || A[0] == '_')) {
                System.out.println("1");
                return;
            }
            memoization = new long[A.length + 1][25][11];
            for (long[][] layer : memoization) {
                for (long[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }
            System.out.println(calculate(A, 0, 0, 10));
        }
        scanner.close();
    }

    static long calculate(char[] A, int index, int prev, int v) {
        if (index == A.length) {
            return prev == 0 ? 1 : 0;
        }
        if (memoization[index][prev][v] != -1) {
            return memoization[index][prev][v];
        }
        long result = 0;
        if (A[index] == '_') {
            for (int j = 0; j < 10; j++) {
                if (index == 0 && j == 0) continue;
                int newPrev = (prev * 10 + j) % 25;
                result += calculate(A, index + 1, newPrev, v);
            }
        } else if (A[index] == 'X') {
            if (v != 10) {
                result += calculate(A, index + 1, (prev * 10 + v) % 25, v);
            } else {
                for (int j = 0; j < 10; j++) {
                    if (index == 0 && j == 0) continue;
                    int newPrev = (prev * 10 + j) % 25;
                    result += calculate(A, index + 1, newPrev, j);
                }
            }
        } else {
            int digit = A[index] - '0';
            result += calculate(A, index + 1, (prev * 10 + digit) % 25, v);
        }
        return memoization[index][prev][v] = result;
    }
}
